<?php declare(strict_types=1);require dirname(__DIR__).'/includes/bootstrap.php';if(PHP_SAPI!=='cli')exit("CLI only\n");$identity=$argv[1]??'';if($identity==='')exit("Usage: php database/enable_admin_mfa.php username-or-email\n");$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$secret='';for($i=0;$i<32;$i++)$secret.=$alphabet[random_int(0,31)];$stmt=db()->prepare('UPDATE admins SET mfa_enabled=1,mfa_secret_encrypted=? WHERE username=? OR email=?');$stmt->execute([encrypt_secret($secret),$identity,$identity]);if($stmt->rowCount()!==1)exit("Admin not found.\n");echo "MFA enabled. Add this secret to the administrator authenticator app, then securely discard it:\n{$secret}\n";
